node -e "
const fs = require('fs');
const buf = fs.readFileSync('/workspace/testbed/docs/customer_report.docx');

// Find local file headers in ZIP
let offset = 0;
const entries = [];
while (offset < buf.length - 4) {
  if (buf.readUInt32LE(offset) === 0x04034b50) { // local file header
    const compMethod = buf.readUInt16LE(offset + 8);
    const compSize = buf.readUInt32LE(offset + 18);
    const uncompSize = buf.readUInt32LE(offset + 22);
    const nameLen = buf.readUInt16LE(offset + 26);
    const extraLen = buf.readUInt16LE(offset + 28);
    const name = buf.toString('utf8', offset + 30, offset + 30 + nameLen);
    const dataStart = offset + 30 + nameLen + extraLen;
    entries.push({ name, compMethod, compSize, uncompSize, dataStart });
    offset = dataStart + compSize;
  } else {
    offset++;
  }
}

const entry = entries.find(e => e.name === 'word/document.xml');
if (!entry) { console.log('word/document.xml not found'); process.exit(1); }

let xml;
if (entry.compMethod === 0) {
  xml = buf.toString('utf8', entry.dataStart, entry.dataStart + entry.uncompSize);
} else {
  const zlib = require('zlib');
  const compressed = buf.slice(entry.dataStart, entry.dataStart + entry.compSize);
  xml = zlib.inflateRawSync(compressed).toString('utf8');
}

// Extract text from XML: get content of <w:t> tags
const texts = [];
const regex = /<w:t[^>]*>([\s\S]*?)<\/w:t>/g;
let match;
while ((match = regex.exec(xml)) !== null) {
  texts.push(match[1]);
}

// Also detect paragraph breaks
const output = xml.replace(/<w:p[^/>]*\/>/g, '\n')
  .replace(/<w:p[ >]/g, '\n<w:p ')
  .replace(/<[^>]*>/g, '')
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&quot;/g, '\"')
  .replace(/^\s*\n/gm, '\n')
  .trim();

console.log(output);
"
